function settingInput(title, id, value, onChange, hint = '') {
  return jsx(OrderSettingInput, { title, id, value, onChange, hint }, id)
}
function OrderSettingInput({ title, id, value, onChange, hint }) {
  const [draft, setDraft] = useState(String(value ?? ''))
  const [invalid, setInvalid] = useState(false)
  const focused = useRef(false)
  useEffect(() => { if (!focused.current) setDraft(String(value ?? '')) }, [value])
  return jsxs('label', { htmlFor: `order-setting-${id}`, style: { display: 'flex', flexDirection: 'column', minWidth: 0, overflowWrap: 'anywhere', gap: 4, fontSize: 13 }, children: [
    jsx('span', { 'data-setting-title': true, style: { minHeight: '2.6em', lineHeight: 1.3, display: 'flex', alignItems: 'flex-end' }, children: title }),
    jsx('input', { id: `order-setting-${id}`, type: 'text', inputMode: 'decimal', value: draft,
      'aria-invalid': Boolean(invalid), 'aria-describedby': invalid ? `order-error-${id}` : undefined,
      onFocus: () => { focused.current = true },
      onChange: event => {
        const text = event.target.value
        setDraft(text)
        // Empty and intermediate text belong to the editor, not persisted math.
        setInvalid(text !== '' && !onChange(text))
      },
      onBlur: () => {
        focused.current = false
        if (!onChange(draft)) setInvalid(draft === '' ? 'required' : true)
        else setInvalid(false)
      },
      style: { boxSizing: 'border-box', minWidth: 0, width: '100%', height: 36, padding: '0 8px', borderRadius: 6, border: '1px solid var(--ui-stroke-secondary)', background: 'var(--ui-bg-secondary)', color: 'var(--ui-text-primary)', font: 'inherit' } }),
    invalid && jsx('small', { id: `order-error-${id}`, role: 'alert', children: invalid === 'required' ? `This setting is required. The previous value (${value}) is still used until you enter a number.` : 'Enter a supported number. Until valid, the previous setting is used.' }),
    hint && jsx('small', { style: muted, children: hint }),
  ] })
}

function defaultHorizon(ctx) {
  try {
    const value = ctx.storage.get('default_horizon', 6)
    return Number.isInteger(value) && value >= 1 && value <= 12 ? value : 6
  } catch { return 6 }
}
export function Settings({ ctx }) {
  const [value, setValue] = useState(() => defaultHorizon(ctx))
  return jsxs('section', { style: pageStyle, children: [
    jsx('h1', { children: 'Stock Runway settings' }),
    jsx(Horizon, { value, title: 'Default forecast horizon', onChange: n => { ctx.storage.set('default_horizon', n); ctx.storage.remove?.('last_horizon'); setValue(n) } }),
    jsx('h2', { children: 'Odoo connection' }),
    jsx('p', { style: { ...muted, maxWidth: '65ch' }, children: 'Optional, read-only access for up to 50 selected SKUs. Set ODOO_URL, ODOO_DB, ODOO_USER and ODOO_API_KEY through Hermes secrets. Never enter a password or API key here or in chat. Use the stock_runway chat tool for Odoo.' }),
  ] })
}

export default {
  id: 'stock-runway', name: 'Stock Runway',
  register(ctx) {
    // SDK guide 343–348: titlebar slots survive chat/full-page navigation.
    // Status bar is optional (hidden/Simple mode), so it is only a trigger.
    const state = atom({ open: false, data: null })
    let dialogMounted = false
    const model = { state, mountDialog: () => {
      dialogMounted = true
      return () => { dialogMounted = false; state.set({ ...state.get(), open: false }) }
    } }
    const open = () => {
      if (dialogMounted) state.set({ open: true, data: quickData(ctx) })
    }
    ctx.register({ id: 'quick-view-host', area: TITLEBAR_AREAS.center, render: () => jsx(RecoveryBoundary, { ctx, children: jsx(QuickView, { model, ctx }) }) })
    ctx.register({ id: 'quick-view-chip', area: 'statusBar.right', order: 70,
      render: () => jsx(Button, { variant: 'ghost', size: 'sm', onClick: open, children: 'Stock' }) })
    ctx.register({ id: 'quick-view', area: PALETTE_AREA, data: { id: 'stock-runway.quick-view', label: 'Stock Runway: quick view', keywords: ['stock', 'inventory', 'runway'], run: open } })
    ctx.register({ id: 'quick-view-keybind', area: KEYBINDS_AREA, data: { id: 'stock-runway.quick-view', label: 'Stock Runway: quick view', category: 'view', defaults: ['mod+shift+i'], run: open } })
    // SDK docs 1100–1149: attributes are untrusted; fail closed before rendering.
    ctx.register({ id: 'card', area: TRANSCRIPT_DIRECTIVE_AREA, data: { name: 'stock-runway', render: ({ attrs }) => {
      const data = decodeCard(attrs)
      return data ? jsx(RunwayTable, { data }) : null
    } } })
    ctx.register({ id: 'route', area: ROUTES_AREA, title: 'Stock Runway', data: { path: '/stock-runway' }, render: () => jsx(RecoveryBoundary, { ctx, children: jsx(Page, { ctx }) }) })
    ctx.register({ id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: '/stock-runway', label: 'Stock Runway', codicon: 'graph' }, order: 70 })
    ctx.register({ id: 'palette', area: PALETTE_AREA, data: { id: 'stock-runway.open', label: 'Open Stock Runway', keywords: ['inventory', 'stock', 'runway'], run: () => host.navigate('/stock-runway') } })
    ctx.registerSettingsPage?.({ id: 'settings', title: 'Stock Runway', icon: 'graph', render: () => jsx(Settings, { ctx }) })
  },
}
